mapper.sql:
FROM mes_report r
JOIN mes_work_order o ON o.id = r.wo_id
JOIN mes_wo_op op ON op.id = r.op_id
JOIN wms_material p ON p.id = o.material_id
LEFT JOIN mes_work_center w ON w.id = op.work_center_id
LEFT JOIN sys_user u ON u.id = r.operator_id
LEFT JOIN sys_dept d ON d.id = u.dept_id
WHERE r.report_date >= #{q.begin} AND r.report_date <= #{q.end}
AND r.operator_id = #{q.operatorId}
AND op.work_center_id = #{q.workCenterId}
AND op.work_center_id IS NULL
AND op.name = #{q.opName}
AND o.material_id = #{q.productId}
AND r.report_date = #{q.day}

    AND (p.code LIKE CONCAT('%', #{q.keyword}, '%') OR p.name LIKE CONCAT('%', #{q.keyword}, '%')
         OR o.wo_no LIKE CONCAT('%', #{q.keyword}, '%'))

mapper.select:
SELECT r.id, r.report_date, r.wo_id, o.wo_no, p.code AS product_code, p.name AS product_name, p.unit,
       op.seq AS op_seq, op.name AS op_name, w.name AS work_center_name, u.nickname AS operator_name,
       r.good_qty, r.scrap_qty, r.hours, op.piece_rate, r.piece_wage, eq.name AS equipment_name, r.remark
FROM mes_report r
JOIN mes_work_order o ON o.id = r.wo_id
JOIN mes_wo_op op ON op.id = r.op_id
JOIN wms_material p ON p.id = o.material_id
LEFT JOIN mes_work_center w ON w.id = op.work_center_id
LEFT JOIN sys_user u ON u.id = r.operator_id
LEFT JOIN mes_equipment eq ON eq.id = r.equipment_id
WHERE r.report_date >= #{q.begin} AND r.report_date <= #{q.end}
AND r.operator_id = #{q.operatorId}
AND op.work_center_id = #{q.workCenterId}
AND op.work_center_id IS NULL
AND op.name = #{q.opName}
AND o.material_id = #{q.productId}
AND r.report_date = #{q.day}

    AND (p.code LIKE CONCAT('%', #{q.keyword}, '%') OR p.name LIKE CONCAT('%', #{q.keyword}, '%')
         OR o.wo_no LIKE CONCAT('%', #{q.keyword}, '%'))

ORDER BY r.report_date DESC, r.id DESC

mapper.sql:
FROM mes_work_order o
JOIN wms_material p ON p.id = o.material_id
LEFT JOIN sys_dept d ON d.id = o.dept_id
WHERE o.status <> 'DRAFT' AND o.plan_end >= #{q.begin} AND o.plan_end <= #{q.end}
AND o.status = #{q.status}
AND o.material_id = #{q.productId}
AND o.dept_id = #{q.deptId}

    AND (p.code LIKE CONCAT('%', #{q.keyword}, '%') OR p.name LIKE CONCAT('%', #{q.keyword}, '%')
         OR o.wo_no LIKE CONCAT('%', #{q.keyword}, '%'))
